if [ -f web/.env ]; then echo "web/.env exists"; else echo "web/.env missing"; fi; if [ -f web/.env.local ]; then echo "web/.env.local exists"; else echo "web/.env.local missing"; fi; node -e '
const fs = require("fs");
for (const file of ["web/.env", "web/.env.local"]) {
  if (!fs.existsSync(file)) continue;
  const text = fs.readFileSync(file, "utf8");
  const keys = ["GITHUB_APP_ID","GITHUB_APP_SLUG","GITHUB_APP_PRIVATE_KEY","COOKIE_SECRET_KEY"];
  for (const key of keys) {
    const match = text.match(new RegExp("^" + key + "=(.*)$", "m"));
    const raw = match ? match[1].trim().replace(/^["'\'']|["'\'']$/g, "") : "";
    const hasBegin = raw.includes("BEGIN");
    console.log(file + " " + key + " set=" + Boolean(raw) + " len=" + raw.length + (key.includes("KEY") ? " pem=" + hasBegin : ""));
  }
}
'

node -e '
const fs = require("fs");
const file = "web/.env";
const text = fs.readFileSync(file, "utf8");
const keys = ["GITHUB_APP_ID","GITHUB_APP_SLUG","GITHUB_APP_PRIVATE_KEY","COOKIE_SECRET_KEY","GITHUB_APP_CLIENT_ID","GITHUB_APP_CLIENT_SECRET"];
for (const key of keys) {
  const match = text.match(new RegExp("^" + key + "=(.*)$", "m"));
  const raw = match ? match[1].trim().replace(/^["'\'']|["'\'']$/g, "") : "";
  const pem = raw.includes("BEGIN");
  console.log(key + " present=" + Boolean(match) + " nonempty=" + Boolean(raw) + " len=" + raw.length + " pem=" + pem);
}
'
